class Solution {
    static boolean isPrime(int n) {
        if (n <= 1) return false;
                if (n <= 3) return true;

                // Skip multiples of 2 and 3
                if (n % 2 == 0 || n % 3 == 0) return false;

                // Check factors of form 6k +/- 1 up to sqrt(n)
                for (int i = 5; i * i <= n; i += 6) {
                    if (n % i == 0 || n % (i + 2) == 0)
                        return false;
                }
                return true;
        
    }
}
